const webhookData = $input.first().json;

// ─── Security: verify X-N8N-Secret header ─────────────────────────────
const receivedSecret = webhookData.headers?.['x-n8n-secret']
                    || webhookData.headers?.['X-N8N-Secret']
                    || '';
const expectedSecret = 'change-me-in-production';

if (receivedSecret !== expectedSecret) {
  throw new Error('401: Invalid X-N8N-Secret header.');
}

const body = webhookData.body || webhookData;

const conversationId = body.conversation_id;
const categoryId     = body.category_id || null;
const messages       = body.messages || [];

if (!conversationId || !messages.length) {
  throw new Error('400: Missing conversation_id or messages.');
}

return [{
  json: {
    conversationId,
    categoryId,
    messages,
    groqModel:   'llama-3.3-70b-versatile',
    groqBaseUrl: 'https://api.groq.com/openai/v1',
  }
}];

const data = $input.first().json;

const systemPrompt = `Tu es un assistant médical. Tu dois résumer une consultation médicale de manière concise et professionnelle.

RÈGLES :
- Résumé en 2-4 phrases maximum
- Mentionne : le motif principal de consultation, les conseils donnés par l'IA, et si un médecin a été consulté
- Ton professionnel et neutre
- Si la conversation est trop courte ou n'a pas de contenu médical, écris un résumé minimal
- Identifie 2 à 5 thèmes clés (mots ou expressions courtes)
- Réponds UNIQUEMENT en français

FORMAT DE SORTIE : JSON valide uniquement, sans markdown, sans blocs de code.
{
  "summary": "<résumé 2-4 phrases>",
  "key_topics": ["<thème1>", "<thème2>"]
}`;

// Format conversation for the LLM
const formatted = data.messages
  .map(m => {
    const role = m.role === 'user' ? 'Patient' : m.role === 'ai' ? 'IA Nexora' : 'Médecin';
    return `[${role}]: ${m.content || '[audio]'}`;
  })
  .join('\n');

const userMessage = `Voici la conversation médicale à résumer :\n\n${formatted}`;

return [{
  json: {
    ...data,
    messages: [
      { role: 'system', content: systemPrompt },
      { role: 'user',   content: userMessage  }
    ],
    temperature: 0.2,
  }
}];

const groqReply = $input.first().json;
const promptData = $('Build Summary Prompt').first().json;

// ─── Extract raw content ───────────────────────────────────────────────
let rawContent = '';
try {
  rawContent = groqReply.choices[0].message.content;
} catch (e) {
  throw new Error('Groq response malformed: ' + JSON.stringify(groqReply));
}

// ─── Parse JSON ────────────────────────────────────────────────────────
let parsed = {};
try {
  const cleaned = rawContent.replace(/```json\n?/g, '').replace(/```\n?/g, '').trim();
  parsed = JSON.parse(cleaned);
} catch (e) {
  // Fallback: use raw text as summary
  parsed = {
    summary:    rawContent.slice(0, 500),
    key_topics: [],
  };
}

const model       = groqReply.model || promptData.groqModel || 'llama-3.3-70b-versatile';
const tokensUsed  = groqReply.usage?.total_tokens || 0;

return [{
  json: {
    summary:     parsed.summary     || '',
    key_topics:  Array.isArray(parsed.key_topics) ? parsed.key_topics : [],
    model,
    tokens_used: tokensUsed,
  }
}];
